      `CLAIM_ADDED sheet=${sheet} by=uma person=Ben amount=40.00 date=2026-03-01`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=20.00 date=2026-03-01 number=1`,
